const $=id=>document.getElementById(id),worldStore=new WorldStore();
const director=new Documentary({enabled:true,reducedMotion:window.matchMedia('(prefers-reduced-motion: reduce)').matches});
let sim,world,tool='observe',speed=1,paused=false,selected=null,following=false,zen=false,lastUI=0,accum=0,last=performance.now(),lastRender=0,toastTimer,saveTimer=0,audio=new Soundscape(),qualityMode='auto',fpsFrames=0,fpsClock=0,fpsMeasured=0,qualityClock=0,renderDue=0,simMs=0,journalFilter='all',notices=[];
async function load(){const s=await worldStore.read();if(s===undefined)return;if(!s||![2,3,4,5,6,7,8].includes(s.version)||!Array.isArray(s.creatures)||!s.climate||!Number.isFinite(s.time))throw Error('El guardado no es válido. Se conserva sin sobrescribirlo.');return s;}

const notifications=new NotificationQueue($('notifications'),{onSelect:id=>selectCreature(id)});
function toast(msg){notifications.push({text:msg,title:'Observatorio'});}
async function save(){try{await worldStore.write(sim.snapshot());$('save-status').textContent='Tu mundo se guarda en este dispositivo';return true;}catch{$('save-status').textContent='No se pudo guardar. La última partida confirmada se conserva.';return false;}}

function escapeHtml(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function ageText(age){return age<1?Math.max(1,Math.round(age*24))+' h':Math.floor(age)+' días';}
function eventAge(time){const d=(sim.time-time)/DAY;return d<.05?'ahora':d<1?'hace '+Math.max(1,Math.floor(d*24))+' h':'día '+(Math.floor(time/DAY)+1);}
function getCreature(){return sim.creatures.find(c=>c.id===selected)||sim.archive.find(c=>c.id===selected);}
function selectCreature(id,follow=false){director.interrupt(45);const c=sim.creatures.find(c=>c.id===id)||sim.archive.find(c=>c.id===id);if(!c)return;selected=id;c.named=true;send({type:'name',id});world.select(id,follow);following=follow;$('detail').hidden=false;$('creature-name').value=c.name;updateDetail();updateSpecies();save();}
function closeDetail(){selected=null;following=false;world.select(null);$('detail').hidden=true;}
function formatGene(key,v){return key==='hue'?(v>=0?'+':'')+Math.round(v*360)+'°':key==='pattern'?Math.round(v*100)+'%':v.toFixed(2)+'×';}
function updateDetail(){if(selected===null)return;const c=getCreature();if(!c){closeDetail();return;}const alive=c.died===undefined,s=SPECIES[c.species],g=c.dna.traits;$('detail-species').textContent=s.name.toUpperCase()+' · '+(c.sex==='F'?'HEMBRA ♀':'MACHO ♂');if(document.activeElement!==$('creature-name'))$('creature-name').value=c.name;$('detail-state').textContent=alive?(c.age<3?'Cría · ':'')+c.state:'Su ciclo terminó';$('detail-description').textContent=s.latin+' · '+s.description;$('detail-age').textContent=ageText(c.age)+' / '+Math.round(c.life)+' d';$('detail-generation').textContent=String(c.generation).padStart(2,'0');$('detail-cells').textContent=alive?(world.cellCounts.get(c.id)||'…')+' / 300':'—';$('energy-value').textContent=alive?Math.round(clamp(c.energy,0,100))+'%':'0%';$('energy-bar').style.width=(alive?clamp(c.energy,0,100):0)+'%';$('detail-lineage').textContent=alive?(c.mother?'Madre: '+c.motherName+' · Padre: '+(c.fatherName||'Sin registro')+'.':'Linaje fundador. Sin progenitores registrados.'):'Día '+(Math.floor(c.died/DAY)+1)+': '+c.name+' '+c.cause+'. Sus restos vuelven al ecosistema.';
 const stats=[['Salud',alive?Math.round(c.health)+'%':'0%'],['Dieta',s.diet],['Hábitat',s.habitat==='water'?'Acuático':s.legs===2?'Terrestre · bípedo':'Terrestre'],['Velocidad',(s.speed*g.speed).toFixed(2)+' u/s'],['Descendientes',c.children],['Alimentos',c.foodEaten],['Recorrido',Math.round(c.distance)+' u'],['Madurez',Math.round(clamp(c.age/3,0,1)*100)+'%'],['Región',CONTINENTS[c.region??0].name],['Linaje',c.lineage??c.id],['Temperatura local',sim.local(c).temperature.toFixed(1)+' °C'],['Humedad del aire',Math.round(sim.local(c).humidity*100)+'%'],['Luz local',Math.round(sim.local(c).light*100)+'%'],['Coste adaptativo',adaptation(c,sim.local(c)).cost.toFixed(2)+'×'],['Reproducción',c.pregnancy?'Gestando':c.stage?'En pareja':c.cooldown>0?'Recuperándose':c.age<3?'Juvenil':'Disponible']];$('technical-stats').innerHTML=stats.map(([k,v])=>`<div><span>${k}</span><b>${escapeHtml(v)}</b></div>`).join('');$('gestation').hidden=!c.pregnancy;if(c.pregnancy)$('gestation').textContent=(s.habitat==='water'?'Puesta':'Gestación')+' · '+Math.round((1-c.pregnancy.remaining/c.pregnancy.total)*100)+'% · Padre: '+c.pregnancy.fatherName;
 $('dna-seed').textContent=c.dna.seed.toString(16).toUpperCase().padStart(8,'0');$('genetic-pattern').textContent=patternName(c.dna)+' · '+(c.mother?'Un alelo de cada progenitor.':'Dos alelos fundadores.')+' La semilla define sus detalles individuales.';$('allele-a').textContent=c.mother?'Madre':'Alelo A';$('allele-b').textContent=c.father?'Padre':'Alelo B';$('gene-rows').innerHTML=Object.entries(TRAITS).map(([key,t])=>`<tr><td>${t.name}</td><td>${formatGene(key,c.dna.alleles[key][0])}</td><td>${formatGene(key,c.dna.alleles[key][1])}</td><td>${formatGene(key,g[key])}</td></tr>`).join('');$('mutation-list').innerHTML=c.dna.mutations.length?'<b>Mutaciones registradas</b><br>'+c.dna.mutations.slice(-5).map(m=>escapeHtml(TRAITS[m.trait].name+' · '+m.origin+' · alelo '+(m.allele===0?'materno':'paterno'))).join('<br>'):'Sin mutaciones nuevas registradas. Sus variantes también pueden ser heredadas.';$('follow').textContent=following?'Dejar de seguir':'Seguir su camino';$('follow').classList.toggle('active',following);$('follow').disabled=!alive;$('animal-call').disabled=!alive;const m=c.mind;const r=c.recovery;$('resilience-detail').textContent=r?(RECOVERY_STATES[r.mode]||r.mode)+' · '+r.sleeps+' letargos · '+r.wakes+' despertares · amortiguación local '+Math.round(r.protection*100)+'%'+(r.mode==='dormant'?' · gasto basal al 18%; sigue envejeciendo.':'.'):'Sin registro de recuperación para esta vida.';updateRelationships(c);$('mind-summary').innerHTML=m?'<b>Aprendizaje situado</b><br>'+m.trials+' experiencias · '+m.successes+' resultados favorables<br>'+m.learnedFrom+' aprendizajes sociales · '+m.placed+' piezas colocadas<br>Última acción: '+(ACTION_NAMES[m.lastAction]||'Explorar')+'<br>Transporta: '+(m.carrying?MATERIALS[m.carrying.type].name:'Nada')+'<br>Cobijo local: '+Math.round((c.shelter||0)*100)+'%<br>Prácticas: '+m.practice.copies+' transmisiones · '+m.practice.routes.length+' lugares recordados':'';
}
function updateSpecies(){const counts=SPECIES.map(s=>sim.creatures.filter(c=>c.species===s.id).length);$('species-list').innerHTML=SPECIES.map((s,i)=>`<button class="species-card" data-species="${s.id}" title="${escapeHtml(s.description)}"><span class="species-orb" style="--color:${s.color}"></span><span><b>${s.name}</b><small>${s.habitat==='water'?'Acuático · aletas':s.diet+' · '+s.legs+' patas'}</small></span><span class="species-number">${counts[i]}</span></button>`).join('');const named=[...sim.creatures.filter(c=>c.named),...sim.archive.filter(c=>c.named)].slice(0,35);$('tracked-list').innerHTML=named.length?named.map(c=>`<button class="tracked-person" data-creature="${c.id}">${escapeHtml(c.name)}<span>${c.died!==undefined?'Ciclo completo':ageText(c.age)}</span></button>`).join(''):'<p class="tracked-empty">Tocá una criatura en el jardín para conocerla. Su historia aparecerá aquí.</p>';}
function updateUI(){updateDirector();updateRecovery();const counts=new Set(sim.creatures.map(c=>c.species));$('day').textContent='Día '+(Math.floor(sim.time/DAY)+1);$('season').textContent=world.focus.z>=0?sim.seasonName:['Otoño','Invierno','Primavera','Verano'][sim.season];$('population').textContent=sim.creatures.length;$('species-count').textContent=counts.size;$('birth-count').textContent=sim.births;
const observed=sim.environment.sample(world.focus.x,world.focus.z);
$('temperature-value').textContent=observed.temperature.toFixed(1)+' °C';$('moisture-value').textContent=Math.round(observed.moisture*100)+'%';$('fertility-value').textContent=Math.round(observed.fertility*100)+'%';$('humidity-value').textContent=Math.round(observed.humidity*100)+'%';$('wind-value').textContent=observed.wind<.3?'Casi en calma':observed.wind<2?'Brisa suave':observed.wind<5?'Moderado':'Fuerte';$('rain-value').textContent=observed.weather==='Lluvia'?'Llueve':observed.cloud>.5?'Nublado':'Sin lluvia';
$('weather-icon').textContent=observed.weather==='Lluvia'?'☂':observed.daylight?'☀':'☾';$('weather-note').textContent=(observed.daylight?'El sol aporta calor. ':'El suelo libera el calor acumulado. ')+(observed.water?'El agua amortigua los cambios térmicos. ':observed.riverDistance<3?'La ribera conserva humedad. ':'La altura y la humedad modulan la temperatura. ')+(observed.weather==='Lluvia'?'Las nubes devuelven agua al suelo.':'El viento transporta vapor entre regiones.');
$('events').innerHTML=sim.events.slice(0,4).map(e=>`<div class="event"><span class="event-icon">${e.icon}</span><div><p>${escapeHtml(e.text)}</p><small>${eventAge(e.time)}</small></div></div>`).join('');const h=sim.history.length?sim.history:[sim.creatures.length,sim.creatures.length],min=Math.max(0,Math.min(...h)-5),max=Math.max(...h)+5,coords=h.map((v,i)=>[i/(h.length-1||1)*260,40-(v-min)/(max-min)*32]);const path=coords.map((v,i)=>(i?'L':'M')+v[0].toFixed(1)+' '+v[1].toFixed(1)).join(' ');$('chart-line').setAttribute('d',path);$('chart-area').setAttribute('d',path+' L260 46 L0 46 Z');$('scene-description').textContent=sim.creatures.length===0?('Sin animales grandes · '+sim.biosphere.summary.phase.toLowerCase()):observed.weather==='Lluvia'?'La lluvia cambia el ritmo del jardín.':sim.births>0?sim.births+' nuevas vidas. Ninguna idéntica a la anterior.':'Todo comienza con una célula.';$('plant-count').textContent=sim.food.length+' plantas · '+new Set(sim.food.map(f=>f.type)).size+' variedades';$('nutrient-count').textContent=Math.round(sim.nutrientsReturned)+' nutrientes devueltos';$('land-size').textContent='Planeta · 4 regiones';$('land-capacity').textContent='Población regulada por alimento';$('expand').disabled=true;$('expand').textContent='Exploración libre';$('culture-summary').textContent=sim.culture.blocks.length+' piezas · '+sim.culture.groups.length+' agrupaciones';$('discovery-progress').textContent=sim.migrations+' cambios de región · '+sim.discoveredRegions.length+' regiones visitadas';const env=sim.environment.sample(world.focus.x,world.focus.z);$('local-climate').textContent=CONTINENTS[env.region].name+' · '+env.biome+' · '+env.phase+' · '+Math.round(env.temperature)+' °C';$('solar-state').textContent=(env.daylight?'☀ ':'☾ ')+String(Math.floor(env.localHour)).padStart(2,'0')+':'+String(Math.floor(env.localHour%1*60)).padStart(2,'0')+' local';$('solar-light').style.width=Math.round(env.light*100)+'%';updateGeodynamics();updateDetail();if(!$('life').hidden)updateSpecies();if($('journal-dialog').open)updateJournal();if($('performance-dialog').open)updatePerformance();if($('culture-dialog').open)updateCulture();}
function chooseTool(next){tool=next;if(next!=='observe')director.interrupt(60);document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('tool-hint').textContent={observe:'Elegí una criatura para conocer su historia',feed:'Tocá la tierra para sembrar alimento',mutate:'Tocá cerca de una criatura para cambiar un rasgo heredable'}[tool];$('world').style.cursor=tool==='observe'?'grab':'crosshair';}
function togglePause(){paused=!paused;send({type:'control',paused});$('pause').textContent=paused?'▷':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Reanudar simulación':'Pausar simulación');$('pause').title=paused?'Reanudar (espacio)':'Pausa (espacio)';toast(paused?'El mundo descansa.':'La vida continúa.');}
let cinemaTimer,lastScreenMessage='';
function revealCinema(){if(!zen)return;document.body.classList.remove('cinema-idle');clearTimeout(cinemaTimer);cinemaTimer=setTimeout(()=>document.body.classList.add('cinema-idle'),4000);}
const screenMode=new ScreenMode({onChange:state=>{
 const entering=state.active&&!zen;zen=state.active;document.body.classList.toggle('zen-mode',zen);
 $('screen-controls').hidden=!zen;$('exit-zen').hidden=!zen;$('zen').setAttribute('aria-pressed',String(zen));
 document.querySelectorAll('.ui').forEach(el=>el.inert=zen);
 if(entering){chooseTool('observe');$('world').tabIndex=-1;$('world').focus({preventScroll:true});}
 if(!zen){clearTimeout(cinemaTimer);document.body.classList.remove('cinema-idle');}
 const message={off:'',requesting:'Solicitando mantener la pantalla encendida…',held:'Pantalla encendida',hidden:'Se reactivará cuando vuelvas a esta pestaña',released:'El sistema liberó la pantalla. Podría apagarse.',blocked:'El navegador no permitió mantener la pantalla encendida.',unsupported:'Este navegador no permite impedir el apagado.'}[state.wake];
 $('screen-status').textContent=message;$('screen-status').dataset.held=String(state.wake==='held');
 $('screen-hint').textContent=state.fullscreen==='unavailable'?'Vista en ventana · no se pudo activar pantalla completa.':'Mové el mouse para ver los controles · Esc o H para salir';
 $('screen-retry').hidden=!zen||(state.fullscreen==='full'&&!['released','blocked'].includes(state.wake));
 if(zen&&(entering||message!==lastScreenMessage))revealCinema();lastScreenMessage=message;
}});
function toggleZen(){void screenMode.toggle();}
function setTab(tab){for(const id of ['ecosystem','life']){$(id).hidden=id!==tab;$('tab-'+id).classList.toggle('active',id===tab);$('tab-'+id).setAttribute('aria-selected',String(id===tab));}if(tab==='life')updateSpecies();}
function rename(){const c=getCreature();if(!c)return;const name=$('creature-name').value.trim().slice(0,28);if(!name){$('creature-name').value=c.name;return;}const old=c.name;c.name=name;c.named=true;send({type:'name',id:c.id,name});for(const child of [...sim.creatures,...sim.archive]){if(child.parent===c.id)child.parentName=name;if(child.otherParent===c.id)child.otherParentName=name;if(child.mother===c.id)child.motherName=name;if(child.father===c.id)child.fatherName=name;if(child.pregnancy?.father===c.id)child.pregnancy.fatherName=name;}save();updateSpecies();if(old!==name)toast('Ahora conocés a '+name+'.');$('creature-name').blur();}
function updateGeodynamics(){const h=sim.hydrology,g=sim.geology,p=world.focus,water=h.sample(p.x,p.z),sum=a=>a.reduce((n,v)=>n+v,0);$('geodynamics-summary').textContent=h.basins.length+' cuencas · '+g.vents.filter(v=>v.erupting).length+' volcanes activos';$('geodynamics-local').textContent='Cuenca '+water.basin+' · caudal '+water.flow.toFixed(3)+' · nieve '+water.snow.toFixed(3)+' · inundación '+water.flood.toFixed(2);if(!$('geodynamics-dialog').open)return;$('geodynamics-metrics').innerHTML='<p>Agua superficial: '+sum(h.surface).toFixed(2)+' · Acuíferos: '+sum(h.groundwater).toFixed(2)+' · Nieve: '+sum(h.snow).toFixed(2)+'</p><p>'+g.totals.quakes+' sismos · '+g.totals.eruptions+' erupciones · '+h.totals.eroded.toFixed(3)+' sedimento erosionado</p>';$('basin-list').innerHTML=h.basins.slice(0,12).map(b=>`<button class="geo-row" data-basin="${b.id}"><b>Cuenca ${b.id}</b><span>${b.cells} celdas · ${b.outlet}</span><small>Caudal ${b.flow.toFixed(3)} · reserva ${b.water.toFixed(2)}${b.flood>.12?' · Desbordada':''}</small></button>`).join('');$('fault-list').innerHTML=g.faults.map(f=>`<button class="geo-row" data-fault="${f.id}"><b>Falla ${f.id+1} · ${f.type}</b><meter min="0" max="${f.threshold}" value="${f.stress}" aria-label="Tensión acumulada"></meter><small>${Math.round(f.stress/f.threshold*100)}% del umbral de ruptura</small></button>`).join('');$('volcano-list').innerHTML=g.vents.map(v=>`<button class="geo-row" data-vent="${v.id}"><b>Volcán ${v.id+1} · ${v.erupting?'En erupción':'Recargando'}</b><span>Reservorio ${Math.round(v.magma/v.capacity*100)}% · roca ${v.rock.toFixed(2)}</span></button>`).join('')||'<p>No hay respiraderos terrestres en estas fronteras de placas.</p>';}
function bindUI(){$('geodynamics-open').onclick=()=>{$('geodynamics-dialog').showModal();updateGeodynamics();};$('geodynamics-close').onclick=()=>$('geodynamics-dialog').close();$('fault-overlay').onchange=e=>{world.landProcesses.overlay=e.target.checked;};$('geodynamics-dialog').addEventListener('click',e=>{const b=e.target.closest('[data-basin],[data-fault],[data-vent]');if(!b)return;const p=b.dataset.basin!==undefined?sim.hydrology.basins.find(v=>v.id===Number(b.dataset.basin)):b.dataset.fault!==undefined?sim.geology.faults.find(v=>v.id===Number(b.dataset.fault)):sim.geology.vents.find(v=>v.id===Number(b.dataset.vent));if(!p)return;director.interrupt(45);following=world.following=false;world.focus={x:p.x,z:p.z};world.desiredDistance=b.dataset.vent!==undefined?15:32;$('geodynamics-dialog').close();});for(const id of ['documentary','screen-documentary'])$(id).onclick=()=>{director.toggle();following=false;world.following=false;updateDirector();};document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>chooseTool(b.dataset.tool)));document.querySelectorAll('[data-speed]').forEach(b=>b.addEventListener('click',()=>{speed=Number(b.dataset.speed);send({type:'control',speed});document.querySelectorAll('[data-speed]').forEach(el=>el.classList.toggle('active',el===b));}));$('pause').onclick=togglePause;$('zen').onclick=toggleZen;$('exit-zen').onclick=()=>void screenMode.stop();$('screen-retry').onclick=()=>void screenMode.retry();window.addEventListener('pointermove',revealCinema,{passive:true});window.addEventListener('pointerdown',revealCinema,{passive:true});window.addEventListener('keydown',revealCinema);$('bones').onclick=()=>{$('bones').classList.toggle('active',world.toggleSkeleton());toast(world.skeleton?'Esqueleto visible: columna y patas con IK.':'Volviste a la piel celular.');};$('zoom-in').onclick=()=>{director.interrupt();world.zoom(.8);};$('zoom-out').onclick=()=>{director.interrupt();world.zoom(1.25);};$('home-view').onclick=()=>{director.interrupt();following=false;world.home();updateDetail();};$('tab-ecosystem').onclick=()=>setTab('ecosystem');$('tab-life').onclick=()=>setTab('life');
$('species-list').onclick=e=>{const b=e.target.closest('[data-species]');if(!b)return;const id=Number(b.dataset.species),c=sim.creatures.find(c=>c.species===id);toast(SPECIES[id].description);if(c)selectCreature(c.id,true);};$('tracked-list').onclick=e=>{const b=e.target.closest('[data-creature]');if(b)selectCreature(Number(b.dataset.creature),sim.creatures.some(c=>c.id===Number(b.dataset.creature)));};$('close-detail').onclick=closeDetail;$('rename').onclick=rename;$('creature-name').addEventListener('keydown',e=>{if(e.key==='Enter')rename();});$('creature-name').addEventListener('change',rename);$('follow').onclick=()=>{following=!following;world.select(selected,following);if(!following)world.home();updateDetail();};$('help').onclick=()=>$('welcome').showModal();$('close-help').onclick=()=>$('welcome').close();$('start-observing').onclick=()=>$('welcome').close();$('reset').onclick=()=>$('reset-dialog').showModal();$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{send({type:'reset'});closeDetail();world.home();paused=false;$('pause').textContent='Ⅱ';$('reset-dialog').close();};$('sound').onclick=toggleSound;$('animal-call').onclick=async()=>{if(!audio.enabled)await toggleSound();audio.call(getCreature(),world.target.x);};$('culture-open').onclick=()=>{updateCulture();$('culture-dialog').showModal();};$('culture-close').onclick=()=>$('culture-dialog').close();$('recovery-open').onclick=()=>{updateRecovery();$('recovery-dialog').showModal();};$('recovery-close').onclick=()=>$('recovery-dialog').close();$('biosphere-sites').onclick=e=>{const button=e.target.closest('[data-colony]');if(!button)return;const p=sim.environment.geo[Number(button.dataset.colony)];if(!p)return;director.interrupt(45);world.following=following=false;world.focus={x:p.x,z:p.z};world.desiredDistance=12;$('recovery-dialog').close();};$('refuge-list').onclick=e=>{const b=e.target.closest('[data-refuge]');if(!b)return;const p=sim.recovery.refuges[Number(b.dataset.refuge)];if(!p)return;director.interrupt(45);world.following=following=false;world.focus={x:p.x,z:p.z};world.desiredDistance=20;$('recovery-dialog').close();};$('open-journal').onclick=()=>{updateJournal();$('journal-dialog').showModal();};$('close-journal').onclick=()=>$('journal-dialog').close();$('journal-filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){journalFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>el.classList.toggle('active',el===b));updateJournal();}};$('journal-list').onclick=e=>{const b=e.target.closest('[data-entity]');if(b&&Number(b.dataset.entity)){selectCreature(Number(b.dataset.entity),false);$('journal-dialog').close();}else if(b){const event=sim.events.find(v=>v.id===Number(b.dataset.event));if(event&&Number.isFinite(event.x+event.z)){director.interrupt(45);following=world.following=false;world.focus={x:event.x,z:event.z};world.desiredDistance=26;$('journal-dialog').close();}}};$('performance').onclick=()=>{updatePerformance();$('performance-dialog').showModal();};$('close-performance').onclick=()=>$('performance-dialog').close();$('quality-mode').onchange=e=>{qualityMode=e.target.value;if(qualityMode!=='auto')world.setQuality(Number(qualityMode));qualityClock=0;frameBudget.reset();};
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();togglePause();}if(e.key.toLowerCase()==='h'&&!e.repeat){e.preventDefault();toggleZen();}if(e.key==='Escape'){if(zen)void screenMode.stop();else closeDetail();}});window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{send({type:'view',visible:!document.hidden});frameBudget.reset();save();last=performance.now();accum=0;audio.visibility(document.hidden);fpsClock=0;fpsFrames=0;renderDue=0;});
world.onClick=({id,x,z})=>{director.interrupt(45);if(tool==='observe'){if(id)selectCreature(id);else closeDetail();}else{send({type:'intervene',tool,x,z});}};world.onOrbit=()=>{director.interrupt();following=false;updateDetail();};}
const eventNames={flood:'El agua ocupa el valle',earthquake:'La tierra libera tensión',eruption:'Fuego bajo la corteza',birth:'Una nueva vida',death:'Un ciclo termina',compost:'Vida que nutre vida',court:'Encuentro',gestation:'Una vida en camino',mutation:'Variación genética',expansion:'El jardín crece',migration:'Una nueva región',social:'Vínculos que cuidan',ecology:'Vidas entrelazadas',culture:'Memoria compartida',recovery:'La vida resiste',weather:'El clima cambia'};
function attachEvents(){sim.onEvent=e=>{audio.event(e,sim);if(['birth','death','compost','mutation','gestation','discovery','collective','migration','social','ecology','culture','recovery','weather','flood','earthquake','eruption'].includes(e.kind)&&!document.hidden)notifications.push({...e,title:eventNames[e.kind]||'El mundo cambia'});};}
function updateCulture(){const x=sim.culture;updateLifeways();$('culture-stats').innerHTML='<p><b>'+x.blocks.length+'</b> piezas colocadas · <b>'+x.groups.length+'</b> agrupaciones observadas</p><p>'+x.totals.collected+' recolecciones · '+x.totals.shared+' intercambios · '+x.totals.contests+' disputas · '+x.totals.learned+' experiencias evaluadas</p><p>Capacidad cognitiva media: '+(sim.creatures.reduce((a,c)=>a+c.dna.traits.cognition,0)/Math.max(1,sim.creatures.length)).toFixed(2)+'×</p>';$('regional-cultures').innerHTML=CONTINENTS.map((r,i)=>{const people=sim.creatures.filter(c=>c.region===i),weights=[0,0,0,0];for(const c of people)c.mind.practice.materials.forEach((v,k)=>weights[k]+=v);const pref=weights.indexOf(Math.max(...weights)),copies=people.reduce((a,c)=>a+c.mind.practice.copies,0);return '<div class=group-row><b>'+r.name+'</b><span>'+people.length+' habitantes · '+(Math.max(...weights)>.1?MATERIALS[pref].name:'Sin preferencia aprendida')+' · '+copies+' transmisiones</span></div>';}).join('');$('group-list').innerHTML=x.groups.length?x.groups.slice(0,8).map(g=>'<div class=group-row><b>Agrupación '+g.id+'</b><span>'+g.blocks+' piezas · '+g.members+' habitantes cercanos · '+(g.maxLevel+1)+' alturas</span></div>').join(''):'<p>Todavía no hay agrupaciones de cuatro o más piezas conectadas.</p>'; }
function updateJournal(){const events=sim.events.filter(e=>journalFilter==='all'||e.kind===journalFilter||(journalFilter==='court'&&e.kind==='gestation'));$('journal-list').innerHTML=events.length?events.map(e=>`<button class="journal-item" data-event="${e.id}" data-entity="${e.entity||0}"><span>${e.icon}</span><div><p>${escapeHtml(e.text)}</p><small>Día ${Math.floor(e.time/DAY)+1} · ${eventNames[e.kind]||'Ecosistema'}</small></div></button>`).join(''):'<p>Todavía no hay acontecimientos de este tipo.</p>';}
function updatePerformance(){const info=world.renderer.info.render;$('performance-stats').innerHTML=`<div><b>${fpsMeasured?fpsMeasured.toFixed(0):'…'}</b><span>FPS medidos</span></div><div><b>${world.cellIndex.toLocaleString('es')}</b><span>Esferas visibles</span></div><div><b>${world.renderMs.toFixed(1)} ms</b><span>Preparación y envío CPU</span></div><div><b>${simMs.toFixed(1)} ms</b><span>Simulación CPU · worker</span></div><div><b>${info.calls}</b><span>Llamadas de dibujo</span></div><div><b>${TIERS[world.qualityTier].name}</b><span>Calidad actual</span></div><div><b>${world.lodStats.full} / ${world.lodStats.simple} / ${world.lodStats.dots}</b><span>Alto / medio / puntos</span></div><div><b>${world.lodStats.hidden}</b><span>Sin dibujar · siguen viviendo</span></div><div><b>${frameBudget.p95.toFixed(1)} / ${frameBudget.p99.toFixed(1)} ms</b><span>Fotograma P95 / P99</span></div><div><b>${world.gpuTimer.ms===null?'No disponible':world.gpuTimer.ms.toFixed(1)+' ms'}</b><span>GPU · consulta asíncrona</span></div><div><b>${lastStepMs.toFixed(1)} ms</b><span>Último paso biológico</span></div><div><b>${transferMs.toFixed(1)} ms</b><span>Preparación y envío del estado</span></div><div><b>${backlog.toFixed(2)} s</b><span>Tiempo simulado pendiente</span></div><div><b>${TIERS[world.qualityTier].cells.toLocaleString('es')}</b><span>Presupuesto máximo de células</span></div>`;}
async function toggleSound(){try{const on=await audio.toggle();$('sound').classList.toggle('active',on);$('sound').setAttribute('aria-label',on?'Silenciar sonidos':'Activar sonidos');$('sound').title=on?'Silenciar sonidos':'Activar sonidos';if(on)toast('Voces del jardín activadas.');}catch{toast('Este navegador no pudo iniciar el sonido.');}}
function frame(now){requestAnimationFrame(frame);if(document.hidden){last=now;return;}const wallDt=Math.max(0,(now-last)/1000),realDt=Math.min(.25,wallDt);last=now;renderDue+=realDt;if(renderDue>=1/60-.0008){director.update(Math.min(.1,(now-lastRender)/1000),sim,world,{paused,following:world.following||tool!=='observe'});world.render(Math.min(.06,(now-lastRender)/1000));const tier=frameBudget.add(now-lastRender,Math.min(.25,(now-lastRender)/1000),world.qualityTier,qualityMode==='auto');if(tier!==world.qualityTier)world.setQuality(tier);lastRender=now;renderDue=Math.max(0,renderDue-1/60);if(renderDue>.06)renderDue=0;fpsFrames++;}fpsClock+=wallDt;qualityClock+=wallDt;if(fpsClock>=2.5){fpsMeasured=fpsFrames/fpsClock;$('performance').textContent=Math.round(fpsMeasured)+' FPS'+(qualityMode==='auto'?' · auto':'');fpsClock=0;fpsFrames=0;}lastUI+=realDt;saveTimer+=realDt;if(lastUI>.8){lastUI=0;updateUI();}if(saveTimer>12){saveTimer=0;save();}if(!paused)audio.update(now,sim,world.target.x);}
let worker;
function send(message){worker?.postMessage(message);}
function accept(state){if(!sim)sim=new Ecosystem(state);else{for(const [key,value] of Object.entries(state))if(key!=='culture'&&key!=='lifeways'&&key!=='recovery'&&key!=='environment'&&key!=='geology'&&key!=='hydrology'&&key!=='biosphere')sim[key]=value;Object.assign(sim.culture,state.culture);Object.assign(sim.lifeways,state.lifeways);Object.assign(sim.recovery,state.recovery);sim.environment.accept(state.environment);sim.geology.accept(state.geology);sim.hydrology.accept(state.hydrology);sim.biosphere.accept(state.biosphere);sim.environmentCache.clear();sim.byId=new Map(sim.creatures.map(c=>[c.id,c]));}sim.pulses=state.pulses||[];}
async function start(){const saved=await load();worker=new Worker(new URL('./simulation-worker.js',import.meta.url),{type:'module'});await new Promise((resolve,reject)=>{let ready=false;worker.onerror=e=>{if(!ready)reject(Error(e.message));else $('save-status').textContent='La simulación se detuvo. Recargá para recuperar el último guardado.';};worker.onmessage=({data:m})=>{if(m.type==='error'){if(!ready)reject(Error(m.message));else toast('La simulación se detuvo: '+m.message);return;}if(m.state){try{accept(stateDecoder.decode(m));}catch(e){send({type:"snapshot"});return;}send({type:'ack',sequence:m.sequence});simMs=m.cpuMs||0;transferMs=m.transferMs||0;backlog=m.backlog||0;lastStepMs=m.lastStepMs||0;if(m.type==='changed')save();if(m.type==='ready'){ready=true;resolve();}if(m.type==='reset'){director.reset();world.actors.clear();save();updateUI();toast('Otro planeta comienza a vivir.');}}if(m.type==='event'){audio.event(m.event,sim);if(['birth','death','compost','mutation','gestation','discovery','collective','migration','social','ecology','culture','recovery','weather','flood','earthquake','eruption'].includes(m.event.kind)&&!document.hidden)notifications.push({...m.event,title:eventNames[m.event.kind]||'El mundo cambia'});}if(m.type==='notice')toast(m.message);};send({type:'init',saved});});world=new World($('world'),sim);bindUI();world.updateEnvironment();world.render(.016);updateUI();chooseTool('observe');save();requestAnimationFrame(frame);setInterval(()=>{if(document.hidden)save();},12000);$('loading').style.opacity='0';setTimeout(()=>$('loading').hidden=true,900);}
start().catch(e=>{console.error(e);$('loading-note').textContent='No se pudo iniciar el planeta. '+e.message;$('loading').querySelector('span').textContent='El observatorio no pudo iniciarse';});

function updateDirector(){for(const id of ['documentary','screen-documentary']){$(id).setAttribute('aria-pressed',String(director.enabled));$(id).textContent=director.enabled?'◉ Documental':'▷ Documental';}$('documentary-caption').hidden=!director.enabled||director.status!=='Documental';$('documentary-title').textContent=director.caption;$('documentary-status').textContent=director.status;}
function updateRelationships(c){const so=c.social,eco=c.ecology;if(!so){$('relationships').textContent='Sin registro social de esta vida.';return;}const links=Object.entries(so.bonds).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([id,value])=>{const p=sim.byId.get(+id);return p?escapeHtml(p.name)+' · '+(value<0?'Tensión':value>.6?'Vínculo fuerte':'Afinidad')+' '+Math.round(Math.abs(value)*100)+'%':'';}).filter(Boolean);$('relationships').innerHTML='<b>Compañía y cuidados</b><p>'+(links.join('<br>')||'Todavía sin vínculos duraderos.')+'</p><p>'+so.careGiven+' cuidados dados · '+so.careReceived+' recibidos</p><b>Su papel ecológico</b><p>'+eco.visits+' visitas florales · '+eco.dispersed+' semillas transportadas<br>Cobertura vegetal: '+Math.round((eco.cover||0)*100)+'%</p><b>Prácticas que recuerda</b><p>'+((c.mind.knowledge||[]).map(k=>escapeHtml(ACTION_NAMES[k.action]||k.action)+' · '+Math.round(k.strength*100)+'% · '+(k.source===c.id?'experiencia propia':'aprendida de #'+k.source)).join('<br>')||'La experiencia empieza a dejar huella.')+'</p>';}
function updateLifeways(){const l=sim.lifeways,t=l.totals;const active=l.traditions.filter(k=>k.holders>1);$('living-web').innerHTML='<div class="web-metrics"><div><b>'+active.length+'</b><span>prácticas compartidas</span></div><div><b>'+t.care+'</b><span>cuidados efectivos</span></div><div><b>'+t.pollinations+'</b><span>flores polinizadas</span></div><div><b>'+t.germinated+'</b><span>descendientes vegetales</span></div></div><p>'+t.transmissions+' aprendizajes por contacto · '+t.forgotten+' recuerdos desvanecidos · '+l.lost.length+' pérdidas colectivas registradas</p><p>'+t.dispersed+' semillas dispersadas · '+Math.round(t.refuge)+' segundos de protección vegetal durante ataques</p>';$('tradition-list').innerHTML=active.slice(0,6).map(k=>'<div class="group-row"><b>'+escapeHtml(ACTION_NAMES[k.action]||k.action)+'</b><span>'+k.holders+' conocedores · origen '+CONTINENTS[k.origin??0].name+'</span></div>').join('');}

function updateRecovery(){const r=sim.recovery,t=r.totals,sleeping=sim.creatures.filter(c=>c.recovery?.mode==='dormant').length,dormant=sim.food.filter(f=>f.recovery?.dormant).length;$('recovery-summary').textContent=r.seeds.length+' semillas en reserva · '+sleeping+' en letargo';$('recovery-note').textContent=sim.biosphere.summary.phase+' · '+sim.biosphere.summary.colonies+' colonias';if(!$('recovery-dialog').open)return;updateBiosphere();$('recovery-metrics').innerHTML='<div class="web-metrics"><div><b>'+r.seeds.length+'</b><span>semillas viables en el suelo</span></div><div><b>'+t.sprouted+'</b><span>germinaciones desde reservas</span></div><div><b>'+dormant+'</b><span>plantas en reposo</span></div><div><b>'+sleeping+'</b><span>habitantes en letargo</span></div></div><p>'+t.plantWakes+' rebrotes desde raíces · '+t.animalWakes+' despertares · '+t.expired+' semillas agotadas</p>';$('recovery-regions').innerHTML=r.regions.map(row=>'<div class="group-row"><b>'+CONTINENTS[row.region].name+' · '+row.phase+'</b><span>'+row.active+' plantas activas · '+row.dormant+' en reposo · '+row.seeds+' semillas · '+row.recoveries+' recuperaciones observadas</span></div>').join('');$('refuge-list').innerHTML=r.refuges.length?r.refuges.filter((p,i,all)=>all.findIndex(q=>q.region===p.region)===i).map(p=>'<button class="refuge-link" data-refuge="'+r.refuges.indexOf(p)+'">Observar microrefugio · '+CONTINENTS[p.region].name+' ↗</button>').join(''):'<p>No se observan núcleos de vegetación activa en microrefugios.</p>';}

function updateBiosphere(){
 const b=sim.biosphere,s=b.summary;
 $('biosphere-metrics').innerHTML='<p><b>'+escapeHtml(s.phase)+'</b> · '+s.colonies+' colonias observables</p><div class="web-metrics">'+['Productores y fitoplancton','Descomponedores','Microfauna y zooplancton'].map((name,i)=>'<div><b>'+s.guildActive[i].toFixed(2)+'</b><span>'+name+'</span></div>').join('')+'<div><b>'+s.dormant.toFixed(2)+'</b><span>reservas latentes</span></div></div><p>Biomasa en unidades del modelo · generación máxima '+s.generation+' · '+b.totals.mutations+' variantes nacidas</p><p>Reciclaje acumulado: '+b.totals.decomposed.toFixed(1)+' · nutrientes disponibles: '+s.minerals.toFixed(1)+'</p>';
 $('biosphere-sites').innerHTML=s.sites.length?s.sites.slice(0,6).map(p=>{
  const group=b.cells[p.cell].guilds[0],q=group.reduce((best,v)=>!best||v.active>best.active?v:best,null);
  return '<button class="geo-row" data-colony="'+p.cell+'"><b>'+CONTINENTS[p.region].name+' · '+(p.water?'Plancton':'Tapete fotosintético')+'</b><span>Linaje '+q.root+' · variante '+q.id+' · generación '+q.generation+'</span><small>Óptimo '+q.genes.optimum.toFixed(1)+' °C · amplitud '+q.genes.breadth.toFixed(1)+' °C · tolerancia a sequía '+Math.round(q.genes.drought*100)+'%</small></button>';
 }).join(''):'<p>Sin colonias visibles por ahora. Las reservas y el ambiente determinan la recuperación.</p>';
}
